import * as S from './schema';

/**
 * A photograph for a product, drawn round inside its pill: from Wikimedia
 * Commons, cropped square and kept small under public/assets/milk/, named
 * by the product's id. Each is free to use with credit, so what it is,
 * whose it is and under what licence is kept here, and shown on hovering it.
 * A product without one is drawn with its words alone.
 */
export type Picture = S.Picture;
// A photograph's page, where it, its author and its licence are from.
const SITES: Record<string, string> = { 'commons.wikimedia.org': 'Wikimedia Commons', 'www.flickr.com': 'Flickr', 'wellcomecollection.org': 'Wellcome Collection' };
const page = (url: string): S.Sourcing => ({ links: [{ name: SITES[new URL(url).hostname] ?? new URL(url).hostname, url }], text: 'The photograph, its author and its licence, from its page.' });
/* A photograph by its page, its author and its licence; what it is, the
   file's name on Commons, unless it is named otherwise. */
const pic = (url: string, author: string, license: string, file = decodeURIComponent(url.split('/wiki/File:').pop()!).replace(/_/g, ' ')): Picture => ({
	file,
	author,
	license,
	sources: page(url),
});
